  .char-rarity{font-size:8px;padding:2px 5px}
  /* ── Phòng trưng bày CG: thích ứng màn cực hẹp ── */
  .cg-domain-bar{gap:3px;margin-bottom:10px}
  .cg-domain-btn{padding:4px 1px;font-size:9px;gap:1px;border-radius:5px;letter-spacing:0}
  .cg-domain-cnt{display:none}
  .cg-cat-toggle{gap:4px;margin-bottom:8px}
  .cg-cat-btn{padding:6px 4px;font-size:11px;letter-spacing:0;border-radius:6px}
  .cg-stats-row{gap:3px;margin-bottom:6px}
  .cg-stat-chip{padding:5px 4px;border-radius:5px}
  .cg-stat-label{font-size:7px;letter-spacing:0}
  .cg-stat-val{font-size:12px}
  .cg-progress-bar{height:3px;margin-bottom:10px}
  .cg-char-grid{gap:4px}
  .cg-char-card{border-radius:8px;border-width:1px}
  .cg-char-overlay{padding:4px 5px}
  .cg-char-name{font-size:9px;letter-spacing:0}
  .cg-char-count{font-size:7px;margin-top:1px}
  .cg-char-prog{height:1px;margin-top:2px}
  .cg-char-thumb-fallback i{font-size:24px}
  .cg-modal-overlay{padding:20px 8px}
  .cg-modal{border-radius:12px}
  .cg-modal-hero{height:80px}
  .cg-modal-hero-name{font-size:14px;letter-spacing:1px}
  .cg-modal-hero-info{bottom:6px;left:10px;right:36px}
  .cg-modal-close{width:26px;height:26px;font-size:12px;top:6px;right:6px}
  .cg-modal-body{padding:8px}
  .cg-modal-stats{gap:4px;margin-bottom:8px;grid-template-columns:1fr 1fr}
  .cg-modal-stat{padding:5px;border-radius:5px}
  .cg-modal-stat-lbl{font-size:7px;letter-spacing:0}
  .cg-modal-stat-val{font-size:13px;margin-top:1px}
  .cg-modal-section-title{font-size:9px;margin:6px 0 4px;letter-spacing:1px}
  .cg-scene-grid{gap:4px}
  .cg-scene-cell{border-radius:6px}
  .cg-scene-name{font-size:7px}
  .cg-scene-max{font-size:6px}
  .cg-scene-info{padding:2px 3px}
  .cg-scene-lock i{font-size:18px}
  .cg-fs-overlay{padding:12px 6px}
  .cg-fs-top{max-width:96vw;padding:0 2px 6px}
  .cg-fs-title{font-size:12px;letter-spacing:1px}
  .cg-fs-sub{font-size:8px}
  .cg-fs-close{width:26px;height:26px;font-size:12px}
  .cg-fs-img-wrap{max-width:96vw}
  .cg-fs-main-img{max-height:60vh;border-width:1px;border-radius:8px}
  .cg-fs-arrow{width:28px;height:40px;font-size:14px}
  .cg-fs-bottom{max-width:96vw;padding:6px 2px 0}
  .cg-fs-dot{width:5px;height:5px}
  .cg-fs-ctr{font-size:10px;min-width:36px}
}
/* ══ Modal bản đồ ══ */
#mapModal{
  position:fixed;inset:0;z-index:9998;
  display:none;align-items:center;justify-content:center;
}
#mapModal.show{display:flex;animation:mmFade .3s ease}
@keyframes mmFade{from{opacity:0}to{opacity:1}}
#mapModal .mm-overlay{
  position:absolute;inset:0;
  background:rgba(0,0,0,.88);
  backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);
  cursor:pointer
}
#mapModal .mm-box{
  position:relative;
  width:96vw;height:92vh;
  background:var(--bg,#0a0612);
  border:1px solid var(--gold,#c9a961);
  border-radius:10px;
  box-shadow:0 16px 60px rgba(0,0,0,.9),0 0 0 1px rgba(201,169,97,.12);
  overflow:hidden;
  animation:mmUp .35s cubic-bezier(.4,0,.2,1)
}
@keyframes mmUp{from{transform:translateY(30px) scale(.95);opacity:0}to{transform:none;opacity:1}}
#mapModal .mm-header{
  position:absolute;top:0;left:0;right:0;height:48px;z-index:10;
  display:flex;align-items:center;justify-content:space-between;
  padding:0 16px;
  background:linear-gradient(180deg,rgba(10,6,18,.95),rgba(10,6,18,.7));
  border-bottom:1px solid rgba(201,169,97,.3)
}
#mapModal .mm-title{
  font-family:var(--fc,serif);font-size:14px;font-weight:700;
  color:var(--gold-bright,#e8c878);letter-spacing:3px;
  display:flex;align-items:center;gap:8px
}
#mapModal .mm-title i{font-size:18px;color:var(--gold,#c9a961)}
#mapModal .mm-close{
  width:34px;height:34px;border-radius:50%;
  background:rgba(255,255,255,.08);
  border:1px solid rgba(201,169,97,.4);
  color:var(--gold,#c9a961);font-size:20px;line-height:1;
  cursor:pointer;display:flex;align-items:center;justify-content:center;
  transition:all .2s;font-family:serif
}
#mapModal .mm-close:hover{
  background:var(--gold,#c9a961);color:#0a0612;
  transform:rotate(90deg)
}
#mapModal .mm-iframe{
  position:absolute;top:48px;left:0;right:0;bottom:0;
  width:100%;height:calc(100% - 48px);
  border:none
}
</style>
</head>
<body>

<!-- Nền trời sao -->
<canvas id="starfield" aria-hidden="true"></canvas>
<div id="nebula" aria-hidden="true"></div>
<div id="rune-circle" aria-hidden="true"></div>

<div id="app">

  <!-- ══ Thanh trạng thái trên ══ -->
  <header class="top-bar" role="banner">
    <div class="brand">
      <div class="brand-sigil">
        <svg viewBox="0 0 36 36" fill="none">
          <polygon points="18,2 32,10 32,26 18,34 4,26 4,10" stroke="#F4C842" stroke-width="1.5" fill="rgba(244,200,66,0.1)"/>
          <polygon points="18,8 27,13 27,23 18,28 9,23 9,13" stroke="#9D6CFF" stroke-width="1" fill="none"/>
          <circle cx="18" cy="18" r="3" fill="#F4C842"/>
        </svg>
      </div>
      <div class="brand-text">
        <div class="brand-title">Biên niên sử Vực Nứt</div>
        <div class="brand-sub">Astral Compass</div>
      </div>
    </div>

    <div class="status-rings">
      <div class="ring-stat stat-clickable" data-stat-info="humanity" title="Bấm xem: Tỷ lệ tàn dư thân chính Cây Nhân Lý">
        <div class="ring-svg" data-ring="hp">
          <svg viewBox="0 0 42 42">
            <circle class="ring-bg" cx="21" cy="21" r="18"/>
            <circle class="ring-fill hp" cx="21" cy="21" r="18" stroke-dasharray="113" stroke-dashoffset="106"/>
          </svg>
          <i class="ring-ico ri-leaf-fill" style="color:var(--emerald)"></i>
        </div>
        <div class="ring-info">
          <span class="ring-label">Nhân lý</span>
          <span class="ring-val" data-era="Thông tin thế giới.Tỷ lệ tàn dư thân chính Cây Nhân Lý">6%</span>
