  html+='<button class="cg-cat-btn'+(cat==='NSFW'?' active':'')+'" onclick="cgSetCategory(\'NSFW\')">NSFW cảnh</button>';
  html+='</div>';

  /* Nút quản lý cache ảnh */
  html+='<div class="cg-cache-bar">';
  html+='<button class="cg-cache-btn" onclick="cgShowImgStats()" title="Xem thống kê cache / xóa cache"><i class="ri-database-2-fill"></i> Cache ảnh</button>';
