      var firstScene=unlockedScenes.find(function(s){return allScenes.indexOf(s)>=0;});
      thumbUrl=CG_BASE_URL+encodeURIComponent(cat)+'/'+encodeURIComponent(c)+'/'+encodeURIComponent(firstScene)+'1.webp';
    }
