      '<div class="cg-modal-hero-grad"></div>'+
      '<div class="cg-modal-close" onclick="cgCloseCharModal()"><i class="ri-close-line"></i></div>'+
      '<div class="cg-modal-hero-info">'+
    '<div class="cg-modal-hero-name">'+displayCgCharName(char)+'</div>'+
        '<div class="cg-modal-hero-sub">'+cat+' · '+done+' / '+allScenes.length+' đã mở khóa</div>'+
      '</div>'+
    '</div>'+
    '<div class="cg-modal-body">'+
      '<div class="cg-modal-stats">'+
        '<div class="cg-modal-stat"><div class="cg-modal-stat-lbl">Đã mở khóa</div><div class="cg-modal-stat-val">'+done+'</div></div>'+
        '<div class="cg-modal-stat"><div class="cg-modal-stat-lbl">Tổng cảnh</div><div class="cg-modal-stat-val">'+allScenes.length+'</div></div>'+
        '<div class="cg-modal-stat"><div class="cg-modal-stat-lbl">Độ hảo cảm</div><div class="cg-modal-stat-val" style="color:'+(favorMax?'#00ff88':'var(--gold-bright)')+'">'+favor+'</div></div>'+
