    nearbyDetailRow('Khoang miệng',body['Khoang miệng'],'ri-emotion-line'),
    nearbyDetailRow('Bàn chân',body['Bàn chân'],'ri-footprint-fill'),
    nearbyDetailRow('Bầu ngực',body['Bầu ngực'],'ri-heart-add-line'),
    nearbyDetailRow('Âm hộ',body['Âm hộ'],'ri-rose-fill'),
    nearbyDetailRow('Hậu môn',body['Hậu môn'],'ri-arrow-up-circle-line')
  ].join('');

  const html='<div class="nearby-detail">'+
    avatar+
